import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"遗漏变量与测量误差","description":"","frontmatter":{"title":"遗漏变量与测量误差","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ovb-measurement-error.md","filePath":"econ/ovb-measurement-error.md","lastUpdated":1789023840000}'),h={name:"econ/ovb-measurement-error.md"};function c(B,a,E,_,u,b){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="遗漏变量与测量误差" tabindex="-1">遗漏变量与测量误差 <a class="header-anchor" href="#遗漏变量与测量误差" aria-label="Permalink to &quot;遗漏变量与测量误差&quot;">​</a></h1><div class="epigraph"><p>漏掉与 $X$ 相关的决定因素，OLS 把别人的效应算进 $\\beta$；用误差污染的 $X$，经典测量误差把 $\\beta$ 往零拉——两种偏误形状不同，都会毁掉上一课的外生。</p><footer>—— 据 Griliches 论经济测量；Wooldridge 遗漏变量公式；对照 Bound, Brown and Mathiowetz 对调查误差</footer></div><p><a href="/econ/clustered-se">上一课</a>把簇内相关下的标准误钉死。推断修完之后，本课缺口才是外生失败的两条经典通道：遗漏变量偏误（OVB）与测量误差。工具变量下一课才出场；本课先把偏误方向钉死，避免一上来就「找一个 IV」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>真模型 \\(Y=\\beta X+\\gamma W+e\\)，\\(\\mathbb{E}[e\\mid X,W]=0\\)，却回归 \\(Y\\) 对 \\(X\\)。FWL 给出</p> \\[\\mathrm{plim}\\,\\hat\\beta=\\beta+\\gamma\\cdot\\delta_{WX}, \\]<p>其中 \\(\\delta_{WX}\\) 是 \\(W\\) 对 \\(X\\) 的总体回归系数。\\(\\gamma\\) 与 \\(\\delta\\) 同号则 OVB 与真效应同向放大。能力漏在工资–教育回归里是教科书原型：教育与能力正相关，能力抬工资，OLS 高估教育回报。</p><p>测量误差另一条。真 \\(X^*\\)，观测 \\(X=X^*+\\nu\\)，经典假设 \\(\\nu\\) 与 \\(X^*\\)、\\(Y\\) 的结构误差独立，则一元回归衰减：\\(\\mathrm{plim}\\,\\hat\\beta=\\beta\\cdot\\frac{\\mathrm{Var}(X^*)}{\\mathrm{Var}(X^*)+\\mathrm{Var}(\\nu)}\\)。多元里「哪一个变量被测错」决定谁衰减、谁把脏吸收到自己身上。缺口是：看见 \\(|\\hat\\beta|\\) 偏小，不要默认「不显著所以没有效应」——可能是衰减。</p><p><span class="marginnote">非经典测量误差（误差与真值相关，如顶编码、报喜不报忧）不必衰减，甚至可以反向。调查收入、自我报告处理，先问误差过程，再套经典公式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>OVB：写出完整回归与短回归，用 FWL 读差。代理变量若与 \\(W\\) 相关、与 \\(e\\) 不相关，可减偏，但不能当无偏证明。固定效应把不随时间变的 \\(W\\) 吸掉——那是后课，本课只标：FE 是对<strong>时不变</strong>遗漏的装置，不是对所有遗漏的装置。</p><p>测量误差：重复测量、工具（用第二次测量当 IV）、外部校准。经典衰减公式只用于自变量误差；因变量的经典误差加大残差方差、不偏斜率。两边同时测错要另写。</p>',12)),(e(),s(p,null,{default:r(()=>[m(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRUE%5B%22%E7%9C%9F%E6%A8%A1%E5%9E%8B%E5%90%AB%20W%22%5D%20--%3E%20SHORT%5B%22%E7%9F%AD%E5%9B%9E%E5%BD%92%22%5D%0A%20%20SHORT%20--%3E%20OVB%5B%22%E5%81%8F%E8%AF%AF%20%CE%B3%C2%B7%CE%B4%22%5D%0A%20%20STAR%5B%22%E7%9C%9F%20X*%22%5D%20--%3E%20MEAS%5B%22%E8%A7%82%E6%B5%8B%20X%3DX*%2B%CE%BD%22%5D%0A%20%20MEAS%20--%3E%20ATT%5B%22%E7%BB%8F%E5%85%B8%3A%20%E5%90%91%E9%9B%B6%E8%A1%B0%E5%87%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OVB 的机制是相关遗漏进入残差，残差不再与 \\(X\\) 正交。测量误差的机制是 \\(X\\) 的变异掺了噪声，信号被稀释。两者可以叠加：教育年限既漏能力，又有误报。方向可能对冲，不能当「所以无偏」。</p><p>与<a href="/econ/potential-outcomes">潜在结果</a>：OVB 是 \\(\\mathbb{E}[Y(0)\\mid D=1]\\neq\\mathbb{E}[Y(0)\\mid D=0]\\) 在线性里的一种参数化。测量误差是处理或结果被错标，连 \\(D\\) 都不是真处理。随机化不自动消灭调查误差。</p><p><span class="marginnote">Griliches 反复强调：许多「生产函数残差」先是测量问题，再是技术。先问数据生成，再问内生。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IV 的存在性证明。不把控制变量清单写成「加到不显著为止」：坏控制（碰撞、中介）可以制造新偏误，Angrist–Pischke 与 Cinelli–Hazlett 的讨论留给设计课。因变量的非经典误差（如审查）走 Tobit 一类，不是本课衰减公式。量化栏的微观结构噪声是价格测量，对象不同，不搬来当教育回报。</p><p>后课默认：短回归必须用 OVB 公式交代方向；经典测量误差默认衰减。下一课在相关遗漏无法观测时，用工具把 \\(X\\) 的外生变异拆出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OVB：\\(+\\gamma\\delta\\)；符号由漏掉变量的效应与其和 \\(X\\) 的相关决定。</li><li>经典自变量测量误差向零衰减；因变量经典误差不偏斜率。</li><li>非经典误差、坏控制，都不在本课公式里。</li><li>FE 只吸时不变遗漏；不是万能。</li><li>出处：Wooldridge 教材 OVB；Griliches 测量传统；Bound, Brown and Mathiowetz 调查误差综述。</li></ul>',9))])}const T=i(h,[["render",c]]);export{f as __pageData,T as default};
